// Prompt builder shared by the browser (own-key mode) and the Supabase Edge Function (supabase/functions/ai).
// Keep this file free of DOM/browser APIs and imports: tools/build_edge_function.py inlines it into the function.

const str = (v, max) => String(v ?? '').slice(0, max).trim();
const int = (v, lo, hi, d) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : d;
};

const TASKS = ['prelims', 'mains', 'evaluate', 'material'];

const SYSTEM = `You are a senior UPSC Civil Services Examination paper-setter and Mains evaluator with two decades of experience.
You write questions that mirror the real UPSC standard: precise wording, conceptual depth, static-current linkage, and plausible distractors.
Accuracy is non-negotiable: use only facts verifiable from standard sources (NCERTs, M. Laxmikanth, Government of India publications, official reports). If unsure of a fact, do not use it.
Always reply with a single valid JSON object and nothing else.`;

function sanitize(task, p = {}) {
  if (!TASKS.includes(task)) throw new Error('Unknown task');
  const base = {
    subject: str(p.subject, 80) || 'General Studies',
    topic: str(p.topic, 160),
    language: p.language === 'hi' ? 'hi' : 'en',
  };
  if (task === 'prelims') {
    return {
      ...base,
      paper: p.paper === 'csat' ? 'csat' : 'gs',
      count: int(p.count, 1, 20, 10),
      difficulty: str(p.difficulty, 30) || 'UPSC standard',
      patterns: (Array.isArray(p.patterns) ? p.patterns : []).map((x) => str(x, 40)).slice(0, 6),
      context: str(p.context, 6000),
    };
  }
  if (task === 'mains') {
    return { ...base, paper: str(p.paper, 20) || 'GS', count: int(p.count, 1, 5, 2), difficulty: str(p.difficulty, 30) || 'UPSC standard', context: str(p.context, 6000) };
  }
  if (task === 'material') {
    return { ...base, paper: str(p.paper, 20) || 'GS' };
  }
  return {
    ...base,
    question: str(p.question, 1200),
    marks: int(p.marks, 5, 20, 10),
    wordLimit: int(p.wordLimit, 50, 400, 150),
    answer: str(p.answer, 9000),
  };
}

const LANG = (l) => (l === 'hi' ? 'Write everything (questions, options, explanations) in clear standard Hindi (Devanagari) as used in the UPSC Hindi-medium paper. Keep JSON keys in English.' : 'Write in clear Indian English as used in UPSC papers.');

function buildMessages(task, raw) {
  const p = sanitize(task, raw);
  let user;

  if (task === 'prelims' && p.paper === 'gs') {
    const patterns = p.patterns.length ? p.patterns.join(', ') : 'statement-based, pair matching, Statement-I/Statement-II, direct';
    user = `Create ${p.count} UPSC Civil Services Preliminary Examination (General Studies Paper I) multiple-choice questions.
Subject: ${p.subject}
Topic: ${p.topic || 'a balanced mix of high-yield topics from this subject’s syllabus'}
Difficulty: ${p.difficulty}
Question patterns to mix: ${patterns}
${p.context ? `Base the questions primarily on this study material (you may add closely related standard facts):\n"""\n${p.context}\n"""\n` : ''}
Format rules:
- Statement-based: put each statement (without numbering) in "statements"; "stem" introduces them (e.g. "Consider the following statements regarding ..."); "ask" is either "How many of the above statements are correct?" with options ["Only one","Only two","All three","None"] (adapt to the number of statements), or "Which of the statements given above is/are correct?" with options like ["1 only","2 only","Both 1 and 2","Neither 1 nor 2"].
- Pair matching: "statements" are pairs written as "X : Y"; "ask" is "How many of the above pairs are correctly matched?".
- Statement-I/Statement-II: statements are ["Statement-I: ...","Statement-II: ..."]; options are the standard four: "Both Statement-I and Statement-II are correct and Statement-II explains Statement-I", "Both Statement-I and Statement-II are correct but Statement-II does not explain Statement-I", "Statement-I is correct but Statement-II is incorrect", "Statement-I is incorrect but Statement-II is correct".
- Direct questions: "statements" is [] and "ask" is "".
- Exactly 4 options and exactly one correct answer. Vary the position of the correct answer.
- "explanation": 2–4 sentences on why the answer is right and why the tempting distractors are wrong.
- "concept": a 2–5 word tag of the concept tested.
${LANG(p.language)}
Return JSON exactly like: {"questions":[{"stem":"","statements":[],"ask":"","options":["","","",""],"answer":0,"explanation":"","concept":""}]} where "answer" is the 0-based index of the correct option.`;
  } else if (task === 'prelims') {
    user = `Create ${p.count} UPSC CSAT (Preliminary General Studies Paper II) questions.
Area: ${p.topic || 'a mix of reading comprehension, logical reasoning, and basic numeracy'}
Difficulty: ${p.difficulty}
${p.context ? `Use this passage/material where suitable:\n"""\n${p.context}\n"""\n` : ''}
Rules:
- For comprehension items include the passage in "passage" (120–220 words) and ask an inference/assumption question in "stem".
- For quant/reasoning, give a precise "stem" with all data needed. Double-check every calculation.
- Exactly 4 options, one correct. "explanation" shows the full worked solution concisely.
${LANG(p.language)}
Return JSON exactly like: {"questions":[{"passage":"","stem":"","statements":[],"ask":"","options":["","","",""],"answer":0,"explanation":"","concept":""}]} where "answer" is the 0-based index.`;
  } else if (task === 'mains') {
    user = `Create ${p.count} UPSC Civil Services Mains questions for ${p.paper}.
Subject: ${p.subject}
Topic: ${p.topic || 'high-yield syllabus themes with contemporary relevance'}
Difficulty: ${p.difficulty}
${p.context ? `Ground the questions in this material:\n"""\n${p.context}\n"""\n` : ''}
Rules:
- Mix 10-mark (150 words) and 15-mark (250 words) questions in authentic UPSC style using directives such as Discuss, Critically examine, Analyse, Evaluate, Comment, Elucidate.${p.paper === 'GS-IV' ? ' For Ethics you may include a short case study (marks 20, 250 words).' : ''}
- "demand": one line on what the examiner actually wants.
- "keywords": 6–10 must-use keywords, data points, committees, articles or judgments.
- "framework": a model answer skeleton with "introduction" (1–2 lines), "body" (5–8 crisp points, multi-dimensional), "conclusion" (1–2 forward-looking lines).
${LANG(p.language)}
Return JSON exactly like: {"questions":[{"question":"","paper":"${p.paper}","marks":10,"wordLimit":150,"directive":"","demand":"","keywords":[],"framework":{"introduction":"","body":[],"conclusion":""}}]}`;
  } else if (task === 'material') {
    user = `Write exam-oriented UPSC Civil Services study notes on one syllabus topic, the way a top coaching faculty would for a serious aspirant.
Subject: ${p.subject} (${p.paper})
Topic: ${p.topic || p.subject}
Rules:
- Accuracy first: use only facts verifiable from NCERTs, standard books (e.g. M. Laxmikanth, Spectrum, G.C. Leong, Shankar IAS) and Government of India sources. If unsure of a fact, leave it out.
- Cover it for both Prelims (facts, articles, years, bodies, examples) and Mains (analysis, dimensions, issues, way forward).
- Be crisp: bullet points, 900–1300 words in total. Quote Constitutional Articles, Acts, committees, judgments, schemes and data where relevant, with years.
- For figures that change over time (rankings, data, counts), add "(verify latest)".
- "sections": 4–7 logical sub-topics, each with 4–8 information-dense points.
- "pyqThemes": themes UPSC has asked on this topic in past papers, described in a few words each (do not invent exact questions or years).
${LANG(p.language)}
Return JSON exactly like: {"title":"","overview":"2–4 sentences","sections":[{"heading":"","points":[""]}],"keyTerms":[{"term":"","meaning":""}],"prelimsFacts":[""],"mainsAngles":[""],"pyqThemes":[""],"currentLinks":[""],"mnemonic":"","quickRevision":[""],"furtherReading":[""]}`;
  } else {
    user = `Evaluate the following UPSC Mains answer like a strict but constructive UPSC examiner.
Question (${p.marks} marks, ${p.wordLimit} words): ${p.question}
Candidate's answer:
"""
${p.answer}
"""
Assess: understanding of the demand/directive, structure (intro–body–conclusion), multi-dimensional coverage, use of facts/data/examples/articles/committees, balance, word limit, and conclusion quality.
Scoring reality: toppers typically score 40–55% of the maximum marks; an average answer gets 25–35%. Score in steps of 0.5.
${LANG(p.language)}
Return JSON exactly like: {"score":0,"outOf":${p.marks},"verdict":"one-line overall judgement","strengths":[""],"improvements":[""],"missingDimensions":[""],"suggestedIntro":"","suggestedConclusion":""}`;
  }

  return [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: user },
  ];
}

/* ---------------- assets/js/providers.js ---------------- */
// AI provider adapters (Google Gemini + OpenAI). Pure fetch, no DOM — runs in the browser and in Node 18+ (api/ai.js).

class ProviderError extends Error {
  constructor(msg, code, status) {
    super(msg);
    this.code = code; // AUTH | RATE | MODEL | API | BLOCKED | EMPTY
    this.status = status;
  }
}

const GEMINI_BASE = 'https://generativelanguage.googleapis.com/v1beta';

// "Auto" tries these in order and moves on when a model is missing or out of free quota.
// The -latest aliases track Google's current Flash models; the 2.5 names are a safety net.
const GEMINI_AUTO_CHAIN = ['gemini-flash-latest', 'gemini-flash-lite-latest', 'gemini-2.5-flash', 'gemini-2.5-flash-lite'];

function split(messages) {
  const system = messages.filter((m) => m.role === 'system').map((m) => m.content).join('\n\n');
  const user = messages.filter((m) => m.role !== 'system').map((m) => m.content).join('\n\n');
  return { system, user };
}

async function geminiOnce({ key, model, messages, signal }) {
  const { system, user } = split(messages);
  const res = await fetch(`${GEMINI_BASE}/models/${encodeURIComponent(model)}:generateContent`, {
    method: 'POST',
    signal,
    headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
    body: JSON.stringify({
      systemInstruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: user }] }],
      generationConfig: { responseMimeType: 'application/json', temperature: 0.7 },
    }),
  });
  const data = await res.json().catch(() => ({}));
  if (res.ok) {
    const cand = data?.candidates?.[0];
    const text = (cand?.content?.parts || []).filter((p) => !p.thought).map((p) => p.text || '').join('');
    if (!text) {
      const reason = data?.promptFeedback?.blockReason || cand?.finishReason || 'unknown';
      throw new ProviderError(`Gemini returned no text (reason: ${reason}). Try rephrasing the topic.`, 'BLOCKED', 200);
    }
    return text;
  }
  const msg = data?.error?.message || `Gemini error (${res.status})`;
  if (res.status === 401 || res.status === 403 || (res.status === 400 && /api key/i.test(msg))) {
    throw new ProviderError('Your Gemini API key was rejected. Re-copy it from Google AI Studio into Settings.', 'AUTH', res.status);
  }
  if (res.status === 429) throw new ProviderError('Gemini free-tier limit reached. Wait a minute and retry — daily limits reset at midnight Pacific time (1:30 PM IST).', 'RATE', 429);
  if (res.status === 404) throw new ProviderError(`Model "${model}" isn't available for your key. Pick another in Settings.`, 'MODEL', 404);
  throw new ProviderError(msg, 'API', res.status);
}

async function callGemini({ key, model, messages, signal }) {
  const chain = !model || model === 'auto' ? GEMINI_AUTO_CHAIN : [model];
  let last;
  for (const m of chain) {
    try {
      return await geminiOnce({ key, model: m, messages, signal });
    } catch (e) {
      if (e.name === 'AbortError' || e.code === 'AUTH' || e.code === 'BLOCKED') throw e;
      last = e;
      // Fall through to the next model on missing model / quota / transient server errors.
      if (!['MODEL', 'RATE'].includes(e.code) && !(e.status >= 500)) throw e;
    }
  }
  throw last;
}

async function listGeminiModels(key) {
  const res = await fetch(`${GEMINI_BASE}/models?pageSize=200`, { headers: { 'x-goog-api-key': key } });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    if ([400, 401, 403].includes(res.status)) throw new ProviderError('Your Gemini API key was rejected. Re-copy it from Google AI Studio.', 'AUTH', res.status);
    throw new ProviderError(data?.error?.message || `Gemini error (${res.status})`, 'API', res.status);
  }
  return (data.models || [])
    .filter((m) => (m.supportedGenerationMethods || []).includes('generateContent'))
    .map((m) => m.name.replace(/^models\//, ''))
    .filter((n) => /^gemini/.test(n) && !/(embed|image|tts|audio|live|vision|computer|robotics|aqa)/i.test(n))
    .sort((a, b) => b.localeCompare(a, undefined, { numeric: true }));
}

async function callOpenAI({ key, model, messages, signal }) {
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    signal,
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` },
    body: JSON.stringify({ model: model || 'gpt-4o-mini', messages, response_format: { type: 'json_object' } }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    if (res.status === 401) throw new ProviderError('Your OpenAI API key was rejected. Check it in Settings.', 'AUTH', 401);
    if (res.status === 429) throw new ProviderError('OpenAI quota exceeded — add billing credit or switch to free Gemini in Settings.', 'RATE', 429);
    throw new ProviderError(data?.error?.message || `OpenAI error (${res.status})`, 'API', res.status);
  }
  return data?.choices?.[0]?.message?.content || '';
}

function callAI({ provider, ...rest }) {
  return provider === 'openai' ? callOpenAI(rest) : callGemini(rest);
}

/* ---------------- Edge Function handler (Deno) ---------------- */
// Secrets (Supabase → Edge Functions → Secrets):
//   GEMINI_API_KEY        required (or OPENAI_API_KEY)
//   ALLOWED_ORIGINS       optional, comma-separated; default: youriasbuddy.com (+www), GitHub Pages URL, localhost
//   AI_DAILY_LIMIT        optional, requests/day for signed-in users (default 25)
//   AI_GUEST_DAILY_LIMIT  optional, requests/day per IP for guests (default 5)
//   GEMINI_MODEL          optional (default "auto")
// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are provided automatically by Supabase.

const env = (k, d = '') => Deno.env.get(k) || d;
const ALLOWED = env('ALLOWED_ORIGINS', 'https://youriasbuddy.com,https://www.youriasbuddy.com,https://raushanraj358.github.io,http://localhost:5173')
  .split(',')
  .map((s) => s.trim().replace(/\/+$/, ''))
  .filter(Boolean);
const USER_LIMIT = Number(env('AI_DAILY_LIMIT', '25'));
const GUEST_LIMIT = Number(env('AI_GUEST_DAILY_LIMIT', '5'));

const admin = createClient(env('SUPABASE_URL'), env('SUPABASE_SERVICE_ROLE_KEY'), { auth: { persistSession: false, autoRefreshToken: false } });

function corsHeaders(origin) {
  return {
    'Access-Control-Allow-Origin': ALLOWED.includes(origin) ? origin : ALLOWED[0] || '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    Vary: 'Origin',
  };
}

Deno.serve(async (req) => {
  const origin = (req.headers.get('origin') || '').replace(/\/+$/, '');
  const headers = { ...corsHeaders(origin), 'Content-Type': 'application/json' };
  const reply = (status, body) => new Response(JSON.stringify(body), { status, headers });

  if (req.method === 'OPTIONS') return new Response('ok', { headers });
  if (req.method !== 'POST') return reply(405, { error: 'Method not allowed' });
  if (!ALLOWED.includes(origin)) return reply(403, { error: 'Forbidden' });

  const provider = env('GEMINI_API_KEY') ? 'gemini' : env('OPENAI_API_KEY') ? 'openai' : null;
  if (!provider) return reply(501, { error: 'Server AI is not configured' });
  const key = provider === 'gemini' ? env('GEMINI_API_KEY') : env('OPENAI_API_KEY');
  const model = provider === 'gemini' ? env('GEMINI_MODEL', 'auto') : env('OPENAI_MODEL', 'gpt-4o-mini');

  let body = {};
  try { body = await req.json(); } catch {}
  let messages;
  try {
    messages = buildMessages(body?.task, body?.params || {});
  } catch (e) {
    return reply(400, { error: e.message });
  }

  // Who is asking: a signed-in user (by id) or a guest (by IP).
  let userId = null;
  const token = (req.headers.get('authorization') || '').replace(/^Bearer\s+/i, '');
  if (token && token.split('.').length === 3) {
    try {
      const { data } = await admin.auth.getUser(token);
      userId = data?.user?.id || null;
    } catch {}
  }
  const ip = (req.headers.get('x-forwarded-for') || '').split(',')[0].trim() || 'unknown';
  const limit = userId ? USER_LIMIT : GUEST_LIMIT;
  let used = 0;
  const { data: n, error } = await admin.rpc('bump_ai_usage', { p_key: userId ? `u:${userId}` : `ip:${ip}` });
  if (error) console.error('bump_ai_usage failed (did you run supabase/schema.sql?)', error.message);
  else used = n;
  if (used > limit) {
    return reply(429, {
      used: limit,
      limit,
      error: userId
        ? `You've used today's ${limit} free AI requests. They reset at midnight (IST), or add your own free Gemini key in Settings for unlimited use.`
        : `Guests get ${limit} free AI requests a day. Sign in with Google (Profile page) to get ${USER_LIMIT} a day.`,
    });
  }

  try {
    const content = await callAI({ provider, key, model, messages });
    return reply(200, { content, used, limit });
  } catch (e) {
    if (e.code === 'RATE') return reply(429, { used, limit, error: 'The free AI is busy right now (shared limit reached). Please try again in a few minutes, or add your own free Gemini key in Settings.' });
    return reply(502, { used, limit, error: e.code === 'AUTH' ? 'The server AI key is invalid.' : e.message || 'AI provider error' });
  }
});
